def stream_rows(resource, transform):
    failed = False
    try:
        while True:
            try:
                row = resource.read_next()
                if row is None:
                    break
                value = transform(row)
            except BaseException:
                failed = True
                raise
            yield value
    finally:
        if failed:
            # Cleanup must not replace a read or transformation failure.
            try:
                resource.close()
            except BaseException:
                pass
        else:
            resource.close()
